@PostMapping("/orders")
public Result<OrderVO> create(@RequestHeader("Idempotency-Key") String key,
                              @RequestBody CreateOrderReq req) {
    String redisKey = "idem:order:" + key;
    // 原子占位：只有第一个请求能设置成功
    Boolean first = redis.opsForValue().setIfAbsent(redisKey, "PROCESSING", Duration.ofMinutes(10));
    if (!Boolean.TRUE.equals(first)) {
        String v = redis.opsForValue().get(redisKey);
        if ("PROCESSING".equals(v)) return Result.fail("请求处理中，请稍后");
        return Result.ok(JSON.parseObject(v, OrderVO.class));   // 返回第一次结果
    }
    try {
        OrderVO vo = orderService.create(key, req);   // 订单表 request_no 唯一索引兜底
        redis.opsForValue().set(redisKey, JSON.toJSONString(vo), Duration.ofHours(24));
        return Result.ok(vo);
    } catch (Exception e) {
        redis.delete(redisKey);                       // 失败允许重试
        throw e;
    }
}

// 本地消息表：下单与“待发送消息”在同一个本地事务
@Transactional(rollbackFor = Exception.class)
public void createOrder(Order order) {
    orderMapper.insert(order);
    outboxMapper.insert(new Outbox(order.getOrderNo(), "order-created", JSON.toJSONString(order), "NEW"));
}

// 定时任务投递，成功后标记；消费端（库存服务）做幂等
@Scheduled(fixedDelay = 2000)
public void relay() {
    for (Outbox m : outboxMapper.findNew(100)) {
        try {
            kafkaTemplate.send(m.getTopic(), m.getBizKey(), m.getPayload()).get(3, TimeUnit.SECONDS);
            outboxMapper.markSent(m.getId());
        } catch (Exception e) {
            outboxMapper.incrRetry(m.getId());   // 超过次数告警人工处理
        }
    }
}

